INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist symmetrische Verschlüsselung nur für kleine Datenmengen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Effizient auch bei großen Daten"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit symmetrischer Verschlüsselung?', 3, '[{"text": "Schnelle Datensicherung", "correct": true, "because": "Ein Schlüssel, hohe Geschwindigkeit"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Langsame Verarbeitung", "correct": false, "because": "Schnelligkeit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat symmetrische Verschlüsselung?', 5, '[{"text": "Ein Schlüssel", "correct": true, "because": "Für Ver- und Entschlüsselung"}, {"text": "Hohe Geschwindigkeit", "correct": true, "because": "Effizienter als asymmetrisch"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) AES ist symmetrisch. b) Sie nutzt zwei Schlüssel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ein Schlüssel für AES"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei symmetrischer Verschlüsselung?', 4, '[{"text": "Schlüsselmanagement", "correct": false, "because": "Kritisch für Sicherheit"}, {"text": "Algorithmuswahl", "correct": false, "because": "Bestimmt Schutz"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob symmetrische Verschlüsselung schneller als asymmetrische ist?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger Rechenaufwand"}, {"text": "Nein", "correct": false, "because": "Effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Algorithmus ist typisch für symmetrische Verschlüsselung?', 3, '[{"text": "AES", "correct": true, "because": "Weit verbreitet und sicher"}, {"text": "RSA", "correct": false, "because": "Asymmetrisch"}, {"text": "SHA-256", "correct": false, "because": "Hashfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet symmetrische Verschlüsselung?', 5, '[{"text": "Hohe Geschwindigkeit", "correct": true, "because": "Effizient bei großen Daten"}, {"text": "Einfache Schlüsselverwendung", "correct": true, "because": "Ein Schlüssel"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Symmetrische Verschlüsselung ist schnell. b) Sie ist unsicherer als asymmetrische. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit hängt von Schlüssel ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für symmetrische Verschlüsselung?', 4, '[{"text": "Ein Schlüssel", "correct": false, "because": "Kern der Methode"}, {"text": "Algorithmus", "correct": false, "because": "Bestimmt Schutz"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt symmetrische Verschlüsselung zwei Schlüssel?', 2, '[{"text": "Nein", "correct": true, "because": "Nur ein Schlüssel"}, {"text": "Ja", "correct": false, "because": "Ein-Schlüssel-Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Algorithmen sind symmetrisch?', 4, '[{"text": "AES", "correct": true, "because": "Symmetrischer Standard"}, {"text": "DES", "correct": true, "because": "Älterer symmetrischer Algorithmus"}, {"text": "RSA", "correct": false, "because": "Asymmetrisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass symmetrische Verschlüsselung unsicher ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicher mit starkem Schlüssel"}, {"text": "Ja", "correct": false, "because": "Sicherheit gewährleistbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei symmetrischer Verschlüsselung?', 3, '[{"text": "Schlüsselstärke", "correct": true, "because": "Bestimmt Sicherheit"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Sekundär"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Symmetrische Verschlüsselung ist effizient. b) Sie schützt nur kleine Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch große Daten möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen nutzen symmetrische Verschlüsselung?', 5, '[{"text": "Dateiverschlüsselung", "correct": true, "because": "Schnell und sicher"}, {"text": "VPNs", "correct": true, "because": "Effizienter Datentunnel"}, {"text": "Maximale Speicherung", "correct": false, "because": "Irrelevant"}, {"text": "Datenbankgröße", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei symmetrischer Verschlüsselung unwichtig?', 3, '[{"text": "Schlüsselverteilung", "correct": false, "because": "Kritisch für Sicherheit"}, {"text": "Algorithmuswahl", "correct": false, "because": "Bestimmt Schutz"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist symmetrische Verschlüsselung für Passwörter geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Hashing bevorzugt"}, {"text": "Ja", "correct": false, "because": "Andere Methode üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob symmetrische Verschlüsselung Schlüssel austauscht?', 2, '[{"text": "Ja", "correct": true, "because": "Schlüssel muss sicher verteilt werden"}, {"text": "Nein", "correct": false, "because": "Verteilung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel wähle ich für symmetrische Verschlüsselung?', 4, '[{"text": "AES-256", "correct": true, "because": "Starker symmetrischer Algorithmus"}, {"text": "Hohe Latenz", "correct": false, "because": "Irrelevant"}, {"text": "Großer Speicher", "correct": false, "because": "Kein Schutzfaktor"}]');
